import type { ComponentProps, ElementType, ReactNode } from "react";

import { IconArrowRight, IconChevronLeft, IconChevronRight, IconClose, IconMenu } from "@rhs-ui/icons";
import { DrilldownBack, DrilldownLeaf, DrilldownOpen, DrilldownPanel, DrilldownSheet, DrilldownStack } from "@rhs-ui/marketing/mobile-nav-drilldown/client";
import { DRILLDOWN_LABELS, ROOT_PANEL, type DrilldownGroup, type DrilldownLabels } from "@rhs-ui/marketing/mobile-nav-drilldown/types";
import { Button } from "@rhs-ui/primitives/button";
import { SheetClose } from "@rhs-ui/primitives/sheet";
import { cn } from "@/lib/utils";

export type { DrilldownGroup, DrilldownLabels, DrilldownLink } from "@rhs-ui/marketing/mobile-nav-drilldown/types";

export interface DrilldownMenuProps extends Omit<ComponentProps<"div">, "children"> {
  /** Your mark, in the bar at the top. */
  brand: ReactNode;
  /** The rows of the root list. A group with links opens a panel; a group without is a plain link. */
  groups: readonly DrilldownGroup[];
  /** The buttons at the foot: sign in, start free. They stay while the panels slide. */
  actions?: ReactNode;
  /** The href of the page you are on: its link gets aria-current and its group is marked. */
  current?: string;
  /** Renders the links. Defaults to "a"; pass your router's Link. */
  linkAs?: ElementType;
  /** A button for the top right of the bar, such as the close of a sheet. */
  closeButton?: ReactNode;
  /** The label of the group whose panel is open first. Left out, the root list. */
  defaultGroup?: string;
  /** The name of the navigation landmark, for a site that is not in English or a page with two menus. */
  navLabel?: string;
  /** Words for the fixed text, for a site that is not in English. */
  labels?: Partial<DrilldownLabels>;
}

const panelId = (index: number) => `group-${index}`;

/* Every class is written out in full, because Tailwind only generates what it can read in the source. */
const rowClass =
  "flex min-h-14 w-full items-center justify-between gap-3 rounded-xl px-4 text-left text-[1.0625rem] font-medium tracking-[-0.01em] outline-none transition-colors duration-150 hover:bg-muted focus-visible:ring-[3px] focus-visible:ring-ring/40 aria-[current=page]:bg-muted motion-reduce:transition-none";
const linkClass =
  "grid gap-0.5 rounded-xl px-4 py-3 outline-none transition-colors duration-150 hover:bg-muted focus-visible:ring-[3px] focus-visible:ring-ring/40 aria-[current=page]:bg-muted motion-reduce:transition-none";
const backClass =
  "inline-flex h-11 items-center gap-1 rounded-lg pr-3 pl-2 text-sm font-medium text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none";

/**
 * The menu itself, without a sheet around it: the mark and a close slot on
 * top, the stack of panels in the middle and the actions at the foot. The root
 * panel lists the groups; each group with links is a panel of its own that
 * slides in from the right, with a Back row that names where it returns to, a
 * title, a link to the group's own page and then its links. Use it inside your
 * own container, or let MobileNavDrilldown put it in a sheet.
 */
export function DrilldownMenu({ brand, groups, actions, current, linkAs: Link = "a", closeButton, defaultGroup, navLabel = "Main", labels: custom, className, ...props }: DrilldownMenuProps) {
  const words = { ...DRILLDOWN_LABELS, ...custom };
  const isCurrent = (href?: string) => href !== undefined && href === current;
  const holdsCurrent = (group: DrilldownGroup) => isCurrent(group.href) || Boolean(group.links?.some((link) => isCurrent(link.href)));
  const first = defaultGroup === undefined ? -1 : groups.findIndex((group) => group.label === defaultGroup);

  return (
    <div data-slot="drilldown-menu" className={cn("flex h-full min-h-0 flex-col bg-background text-foreground", className)} {...props}>
      <div className="flex h-14 shrink-0 items-center justify-between gap-3 border-b border-border pr-2 pl-6">
        <div className="min-w-0">{brand}</div>
        {closeButton}
      </div>

      <nav aria-label={navLabel} className="relative min-h-0 flex-1 overflow-clip">
        <DrilldownStack defaultPanel={first === -1 ? undefined : panelId(first)} className="absolute inset-0">
          <DrilldownPanel id={ROOT_PANEL} label={words.menu}>
            <div className="relative min-h-0 flex-1 overflow-y-auto overscroll-contain p-2">
              <ul className="grid gap-0.5">
                {groups.map((group, index) => (
                  <li key={`${group.label}-${index}`}>
                    {group.links?.length ? (
                      <DrilldownOpen target={panelId(index)} className={rowClass}>
                        <span className="flex min-w-0 items-center gap-2.5">
                          <span className="truncate">{group.label}</span>
                          {holdsCurrent(group) ? (
                            <>
                              <span aria-hidden="true" className="size-1.5 shrink-0 rounded-full bg-foreground" />
                              <span className="sr-only">({words.currentSection})</span>
                            </>
                          ) : null}
                        </span>
                        <IconChevronRight aria-hidden="true" className="size-5 shrink-0 text-muted-foreground" />
                      </DrilldownOpen>
                    ) : (
                      <DrilldownLeaf>
                        <Link href={group.href ?? "#"} aria-current={isCurrent(group.href) ? "page" : undefined} className={rowClass}>
                          {group.label}
                        </Link>
                      </DrilldownLeaf>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          </DrilldownPanel>

          {groups.map((group, index) =>
            group.links?.length ? (
              <DrilldownPanel key={`${group.label}-${index}`} id={panelId(index)} label={group.label} className="-left-px border-l border-border">
                <div className="shrink-0 px-2 pt-2">
                  <DrilldownBack aria-label={words.back.replace("{name}", words.menu)} className={backClass}>
                    <IconChevronLeft aria-hidden="true" className="size-5" />
                    {words.menu}
                  </DrilldownBack>
                </div>
                <div className="relative min-h-0 flex-1 overflow-y-auto overscroll-contain px-2 pb-4">
                  <h2 className="px-4 pt-3 pb-4 text-[1.75rem] leading-none font-medium tracking-[-0.04em]">{group.label}</h2>
                  <ul className="grid gap-0.5">
                    {group.href ? (
                      <li className="mb-1 border-b border-border pb-1">
                        <DrilldownLeaf>
                          <Link href={group.href} aria-current={isCurrent(group.href) ? "page" : undefined} className={cn(linkClass, "flex items-center justify-between gap-3 text-base font-medium")}>
                            {words.all.replace("{name}", group.label)}
                            <IconArrowRight aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
                          </Link>
                        </DrilldownLeaf>
                      </li>
                    ) : null}
                    {group.links.map((link) => (
                      <li key={`${link.label}-${link.href}`}>
                        <DrilldownLeaf>
                          <Link href={link.href} aria-current={isCurrent(link.href) ? "page" : undefined} className={linkClass}>
                            <span className="text-base font-medium">{link.label}</span>
                            {link.description ? <span className="text-sm leading-snug text-muted-foreground">{link.description}</span> : null}
                          </Link>
                        </DrilldownLeaf>
                      </li>
                    ))}
                  </ul>
                </div>
              </DrilldownPanel>
            ) : null,
          )}
        </DrilldownStack>
      </nav>

      {actions ? <div className="grid shrink-0 gap-2 border-t border-border p-4 pb-[max(1rem,env(safe-area-inset-bottom))] *:w-full">{actions}</div> : null}
    </div>
  );
}

export interface MobileNavDrilldownProps extends Pick<DrilldownMenuProps, "brand" | "groups" | "actions" | "current" | "linkAs" | "navLabel" | "labels"> {
  /** Open or closed, when you control it. Pair with onOpenChange. */
  open?: boolean;
  /** Whether the sheet starts open, when you do not control it. */
  defaultOpen?: boolean;
  /** Called when the sheet opens or closes, by the visitor or because a link was followed. */
  onOpenChange?: (open: boolean) => void;
  /** The edge the sheet slides in from. */
  side?: "left" | "right";
  /** Your own button to open the sheet with; it replaces the menu button. */
  trigger?: ReactNode;
  /** Classes for the menu button. It is shown at every width: hide it from md up with className="md:hidden". */
  className?: string;
}

/**
 * The phone menu that navigates the way a native app does. A menu button opens
 * a sheet from the left that holds a stack of panels: the root lists your
 * groups, and a group with links slides them in as a panel of its own, with a
 * Back row that names where it returns to. Focus moves to the first row of a
 * panel that opens and back to the group's row when you return, Escape goes up
 * a level and only then closes the sheet, and the panels you cannot see are
 * inert, so their links are never tabbable. Reduced motion swaps the slide for
 * an instant change. Better than folding groups open in place once a group
 * holds more than six links. The sheet starts over at the root each time it
 * opens, and every link closes it. onOpenChange is a function, so use the menu
 * from a Client Component if you control it.
 */
export function MobileNavDrilldown({ brand, groups, actions, current, linkAs, open, defaultOpen, onOpenChange, side = "left", trigger, navLabel, labels: custom, className }: MobileNavDrilldownProps) {
  const words = { ...DRILLDOWN_LABELS, ...custom };

  return (
    <DrilldownSheet
      trigger={
        trigger ?? (
          <Button variant="ghost" size="icon" className={className} aria-label={words.open}>
            <IconMenu size={18} />
          </Button>
        )
      }
      title={words.menu}
      description={words.description}
      side={side}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      <DrilldownMenu
        brand={brand}
        groups={groups}
        actions={actions}
        current={current}
        linkAs={linkAs}
        navLabel={navLabel}
        labels={custom}
        closeButton={
          <SheetClose asChild>
            <Button variant="ghost" size="icon" aria-label={words.close}>
              <IconClose size={18} />
            </Button>
          </SheetClose>
        }
      />
    </DrilldownSheet>
  );
}

"use client";

import { createContext, useCallback, useContext, useEffect, useId, useRef, useState, type ComponentProps, type KeyboardEvent, type ReactNode, type RefObject } from "react";
import { Slot } from "radix-ui";

import { ROOT_PANEL } from "@rhs-ui/marketing/mobile-nav-drilldown/types";
import { Sheet, SheetContent, SheetDescription, SheetTitle, SheetTrigger } from "@rhs-ui/primitives/sheet";
import { cn } from "@/lib/utils";

interface Stack {
  baseId: string;
  /** The panels the visitor has been through, from the root to the one on screen. */
  trail: readonly string[];
  push: (id: string) => void;
  pop: () => void;
  panels: RefObject<Map<string, HTMLElement>>;
  openers: RefObject<Map<string, HTMLElement>>;
}

const StackContext = createContext<Stack | null>(null);
/** Set by the sheet: what a link does to the sheet it sits in, which is to close it. */
const DismissContext = createContext<(() => void) | null>(null);
/** Set by the sheet: lets Escape ask the stack to go up one level before the sheet closes. */
const EscapeContext = createContext<((handler: (() => boolean) | null) => void) | null>(null);

function useStack(): Stack {
  const stack = useContext(StackContext);
  if (!stack) throw new Error("A drill-down part must sit inside a DrilldownStack.");
  return stack;
}

export interface DrilldownStackProps extends ComponentProps<"div"> {
  /** The id of the panel to show first. Left out, the root list. */
  defaultPanel?: string;
}

/**
 * The stack of panels: the state of which one is on screen, and the keys that
 * move through it. Escape goes up one level, Up, Down, Home and End move
 * between the rows of the panel on screen. Focus follows the visitor: it moves
 * to the first row of a panel that opens, and back to the row that opened it
 * when they return.
 */
export function DrilldownStack({ defaultPanel, className, children, onKeyDown, ...props }: DrilldownStackProps) {
  const baseId = useId();
  const registerEscape = useContext(EscapeContext);
  const [trail, setTrail] = useState<readonly string[]>(defaultPanel && defaultPanel !== ROOT_PANEL ? [ROOT_PANEL, defaultPanel] : [ROOT_PANEL]);
  // The trail as last committed, for the key handlers, which must not wait for a render.
  const shown = useRef(trail);
  const panels = useRef(new Map<string, HTMLElement>());
  const openers = useRef(new Map<string, HTMLElement>());

  const push = useCallback((id: string) => setTrail((before) => (before.at(-1) === id ? before : [...before, id])), []);
  const pop = useCallback(() => setTrail((before) => (before.length > 1 ? before.slice(0, -1) : before)), []);

  // Focus follows what the visitor did. A first render, which changes nothing, moves nothing. The panel is still sliding when it gets
  // focus, so the focus must not scroll: a browser would scroll the clipped stack sideways to reach it and leave the wrong panel in view.
  useEffect(() => {
    const before = shown.current;
    shown.current = trail;
    if (before === trail) return;
    if (trail.length > before.length) panels.current.get(trail.at(-1) ?? "")?.querySelector<HTMLElement>("[data-drill-item]")?.focus({ preventScroll: true });
    else openers.current.get(before.at(-1) ?? "")?.focus({ preventScroll: true });
  }, [trail]);

  useEffect(() => {
    if (!registerEscape) return;
    registerEscape(() => {
      if (shown.current.length < 2) return false;
      pop();
      return true;
    });
    return () => registerEscape(null);
  }, [registerEscape, pop]);

  function handleKeys(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    // A sheet has already had its Escape by now: it either went up a level or closed, and says so by preventing the default.
    if (event.defaultPrevented) return;
    if (event.key === "Escape" && shown.current.length > 1) {
      event.preventDefault();
      event.stopPropagation();
      pop();
      return;
    }
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp" && event.key !== "Home" && event.key !== "End") return;
    const panel = panels.current.get(shown.current.at(-1) ?? "");
    const rows = panel ? Array.from(panel.querySelectorAll<HTMLElement>("[data-drill-item], [data-drill-back]")) : [];
    const index = rows.indexOf(document.activeElement as HTMLElement);
    if (index === -1) return;
    event.preventDefault();
    const last = rows.length - 1;
    const next = event.key === "Home" ? 0 : event.key === "End" ? last : Math.min(last, Math.max(0, index + (event.key === "ArrowDown" ? 1 : -1)));
    rows[next]?.focus();
  }

  return (
    <StackContext.Provider value={{ baseId, trail, push, pop, panels, openers }}>
      <div data-slot="drilldown-stack" className={cn("relative overflow-clip", className)} onKeyDown={handleKeys} {...props}>
        {children}
      </div>
    </StackContext.Provider>
  );
}

export interface DrilldownPanelProps extends Omit<ComponentProps<"div">, "id"> {
  /** The id of the panel: the root's for the list of groups, a group's own for its links. */
  id: string;
  /** The name a screen reader gives the panel. */
  label: string;
}

/**
 * One panel of the stack. All of them stay in the page; the one on screen sits
 * at rest, the ones the visitor has passed are nudged left behind it and the
 * rest wait off the right edge, and every panel that is not on screen is inert,
 * so its links are neither tabbable nor read out. Under reduced motion the
 * panels change place without sliding.
 */
export function DrilldownPanel({ id, label, className, children, ...props }: DrilldownPanelProps) {
  const stack = useStack();
  const { panels } = stack;
  const position = stack.trail.indexOf(id);
  const state = position === -1 ? "ahead" : position === stack.trail.length - 1 ? "active" : "behind";
  const register = useCallback(
    (node: HTMLDivElement | null) => {
      if (!node) return;
      panels.current.set(id, node);
      return () => {
        panels.current.delete(id);
      };
    },
    [id, panels],
  );

  return (
    <div
      ref={register}
      id={`${stack.baseId}-${id}`}
      role="group"
      aria-label={label}
      data-slot="drilldown-panel"
      data-state={state}
      inert={state !== "active"}
      className={cn(
        "absolute inset-0 flex flex-col bg-background transition-transform duration-300 ease-[cubic-bezier(0.2,0.7,0.2,1)] motion-reduce:transition-none",
        state === "active" && "translate-x-0",
        state === "behind" && "-translate-x-1/4",
        state === "ahead" && "translate-x-full",
        className,
      )}
      {...props}
    >
      {children}
    </div>
  );
}

export interface DrilldownOpenProps extends Omit<ComponentProps<"button">, "type" | "onClick"> {
  /** The id of the panel this row opens. */
  target: string;
}

/** A row of the root list that opens a group's panel. A button, because it does not leave the page. */
export function DrilldownOpen({ target, className, children, ...props }: DrilldownOpenProps) {
  const stack = useStack();
  const { openers } = stack;
  const register = useCallback(
    (node: HTMLButtonElement | null) => {
      if (!node) return;
      openers.current.set(target, node);
      return () => {
        openers.current.delete(target);
      };
    },
    [target, openers],
  );

  return (
    <button
      ref={register}
      type="button"
      data-drill-item=""
      aria-expanded={stack.trail.includes(target)}
      aria-controls={`${stack.baseId}-${target}`}
      onClick={() => stack.push(target)}
      className={className}
      {...props}
    >
      {children}
    </button>
  );
}

/** The Back row of a group's panel: goes up one level. */
export function DrilldownBack({ className, children, ...props }: Omit<ComponentProps<"button">, "type" | "onClick">) {
  const stack = useStack();
  return (
    <button type="button" data-drill-back="" onClick={stack.pop} className={className} {...props}>
      {children}
    </button>
  );
}

/**
 * Wraps one link, rendered on the server with your router's Link: it joins the
 * rows the arrow keys move between, and closes the sheet around it when the
 * visitor follows it. Outside a sheet it does nothing more.
 */
export function DrilldownLeaf({ children }: { children: ReactNode }) {
  const dismiss = useContext(DismissContext);
  return (
    <Slot.Root data-drill-item="" onClick={() => dismiss?.()}>
      {children}
    </Slot.Root>
  );
}

export interface DrilldownSheetProps {
  /** The element that opens the sheet: a button. */
  trigger: ReactNode;
  /** The title of the sheet, for a screen reader. */
  title: string;
  /** What the sheet is for, for a screen reader. */
  description: string;
  /** The edge it slides in from. */
  side?: "left" | "right";
  /** Open or closed, when you control it. Pair with onOpenChange. */
  open?: boolean;
  /** Whether the sheet starts open, when you do not control it. */
  defaultOpen?: boolean;
  /** Called when the sheet opens or closes, by the visitor or because a link was followed. */
  onOpenChange?: (open: boolean) => void;
  /** Classes for the sheet. */
  className?: string;
  /** The menu: a DrilldownStack and whatever frames it. */
  children: ReactNode;
}

/**
 * The sheet around the menu. Escape goes up a level first and only closes the
 * sheet from the root, and every panel starts over at the root the next time it
 * opens, because the stack lives inside the sheet's content. Under reduced
 * motion the sheet itself appears and goes without sliding, like its panels.
 */
export function DrilldownSheet({ trigger, title, description, side = "left", open, defaultOpen = false, onOpenChange, className, children }: DrilldownSheetProps) {
  const [own, setOwn] = useState(defaultOpen);
  const escape = useRef<(() => boolean) | null>(null);
  const register = useCallback((handler: (() => boolean) | null) => {
    escape.current = handler;
  }, []);
  const isOpen = open ?? own;
  const change = (next: boolean) => {
    if (open === undefined) setOwn(next);
    onOpenChange?.(next);
  };

  return (
    <EscapeContext.Provider value={register}>
      <DismissContext.Provider value={() => change(false)}>
        <Sheet open={isOpen} onOpenChange={change}>
          <SheetTrigger asChild>{trigger}</SheetTrigger>
          <SheetContent
            side={side}
            showCloseButton={false}
            data-slot="mobile-nav-drilldown"
            onEscapeKeyDown={(event) => {
              if (escape.current?.()) event.preventDefault();
            }}
            className={cn("w-[min(24rem,88vw)] gap-0 p-0 motion-reduce:data-[state=closed]:animate-none motion-reduce:data-[state=open]:animate-none", className)}
          >
            <SheetTitle className="sr-only">{title}</SheetTitle>
            <SheetDescription className="sr-only">{description}</SheetDescription>
            {children}
          </SheetContent>
        </Sheet>
      </DismissContext.Provider>
    </EscapeContext.Provider>
  );
}

/** A link inside the panel of a group. */
export interface DrilldownLink {
  label: string;
  href: string;
  /** One line under the label, such as what the page is for. */
  description?: string;
}

/**
 * A row of the root list. With `links` it opens a panel of its own; without,
 * it is a plain link to `href`. The shape is the one MobileMenu takes, so one
 * list of data can feed both menus.
 */
export interface DrilldownGroup {
  label: string;
  /** The group's own page. A group with links offers it as the first row of its panel; a group without links needs it. */
  href?: string;
  links?: readonly DrilldownLink[];
}

/** The fixed words, for a site that is not in English. */
export interface DrilldownLabels {
  /** The name of the menu: the title of the sheet, the label of the root panel and what the Back row of a group says. */
  menu: string;
  /** What the sheet is for, read to a screen reader when it opens. */
  description: string;
  /** The name of the button that opens the sheet. */
  open: string;
  /** The name of the button that closes it. */
  close: string;
  /** The name of the Back row for a screen reader. {name} is the panel it returns to. */
  back: string;
  /** The first row of a group's panel, a link to the group's own page. {name} is the group. */
  all: string;
  /** Said after a group that holds the page you are on. */
  currentSection: string;
}

export const DRILLDOWN_LABELS: DrilldownLabels = {
  menu: "Menu",
  description: "Every page of this site. A row with a chevron opens its own panel.",
  open: "Open the menu",
  close: "Close the menu",
  back: "Back to {name}",
  all: "All {name}",
  currentSection: "holds the current page",
};

/** The id of the first panel, the one that lists the groups. */
export const ROOT_PANEL = "root";
